import { randomBytes } from "node:crypto";
import type { ClawforceConfig } from "./types.js";

export function generateEnv(config: ClawforceConfig): string {
  const gatewayToken = randomBytes(32).toString("hex");

  const hooksToken = randomBytes(32).toString("hex");
  const credentialMode = config.models.credential_mode ?? "env";

  const lines = [
    "# Generated by Clawforce",
    `# Deployment: ${config.name}`,
    "# DO NOT COMMIT THIS FILE TO VERSION CONTROL",
    "",
    `GATEWAY_TOKEN=${gatewayToken}`,
    `HOOKS_TOKEN=${hooksToken}`,
  ];

  if (credentialMode === "env") {
    lines.push(`ANTHROPIC_API_KEY=${config.models.api_key ?? ""}`);
    if (config.models.auth_profile) {
      lines.push(
        "# NOTE: models.auth_profile is configured but ignored because credential_mode=env",
      );
    }
  } else {
    lines.push("# Credential mode uses OpenClaw auth profile, not provider env vars");
    lines.push(`OPENCLAW_AUTH_PROFILE=${config.models.auth_profile ?? ""}`);
    if (config.models.api_key) {
      lines.push(
        "# NOTE: models.api_key is configured but ignored because credential_mode=auth_profile",
      );
    }
  }

  if (config.dashboard?.auth?.enabled) {
    const authSecret = randomBytes(32).toString("hex");
    lines.push("");
    lines.push("# Dashboard authentication");
    lines.push(`AUTH_SECRET=${authSecret}`);
  }

  const slackWebhookUrl = config.alerts?.notifications?.slack?.webhook_url;
  if (typeof slackWebhookUrl === "string" && slackWebhookUrl.length > 0) {
    lines.push("");
    lines.push("# Alert notification secrets");
    lines.push(`CLAWFORCE_ALERTS_SLACK_WEBHOOK_URL=${slackWebhookUrl}`);
  }

  const emailPassword = config.alerts?.notifications?.email?.password;
  if (typeof emailPassword === "string" && emailPassword.length > 0) {
    if (!lines.includes("# Alert notification secrets")) {
      lines.push("");
      lines.push("# Alert notification secrets");
    }
    lines.push(`CLAWFORCE_ALERTS_EMAIL_PASSWORD=${emailPassword}`);
  }

  return lines.join("\n") + "\n";
}
